(function(){
  const $=(s,r=document)=>r.querySelector(s); const $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
  const toast=(message)=>{let el=$('#toast');if(!el){el=document.createElement('div');el.id='toast';el.className='toast';el.setAttribute('role','status');el.setAttribute('aria-live','polite');document.body.appendChild(el)}el.textContent=message;el.classList.add('show');clearTimeout(el._t);el._t=setTimeout(()=>el.classList.remove('show'),1800)};
  $$('[data-toast]').forEach(el=>el.addEventListener('click',()=>toast(el.dataset.toast)));
  const closeModal=(modal)=>{if(!modal)return;modal.classList.remove('open');modal._returnFocus?.focus()};
  const openModal=(trigger)=>{const modal=$('#'+trigger.dataset.openModal);if(!modal)return;modal._returnFocus=trigger;modal.classList.add('open');const target=$('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled])',modal);requestAnimationFrame(()=>target?.focus())};
  $$('[data-open-modal]').forEach(el=>el.addEventListener('click',()=>openModal(el)));
  $$('[data-close-modal]').forEach(el=>el.addEventListener('click',()=>closeModal(el.closest('.modal'))));
  $$('.modal').forEach(el=>{const dialog=$('.dialog',el);if(dialog){dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true')}el.addEventListener('click',e=>{if(e.target===el)closeModal(el)})});
  $$('[data-secret-toggle]').forEach(btn=>btn.addEventListener('click',()=>{const target=$('#'+btn.dataset.secretToggle);if(!target)return;const hidden=target.dataset.hidden!=='false';target.dataset.hidden=String(!hidden);target.textContent=hidden?(target.dataset.value||'示例内容已隐藏'):'••••••••••••';btn.textContent=hidden?'隐藏':'显示'}));
  $$('[data-choice]').forEach(el=>el.addEventListener('click',()=>{const group=el.parentElement;$$('[data-choice]',group).forEach(x=>x.classList.remove('selected'));el.classList.add('selected')}));
  const importBtn=$('#saveProfileBtn'); if(importBtn) importBtn.addEventListener('click',()=>{const input=$('#claimCode');const msg=$('#importMessage');if(!input.value.trim()){msg.className='notice warning';msg.innerHTML='<strong>尚未粘贴 SyncKey</strong><span>请粘贴管理员提供的 SyncKey 导入码或导入链接。</span>';return}msg.className='notice success';msg.innerHTML='<strong>连接检查通过</strong><span>SyncKey 已保存。正在读取本机授权摘要与连接状态。</span>';setTimeout(()=>location.href='client-sync.html',650)});
  const run=$('#runSyncBtn'),stop=$('#stopSyncBtn'),bar=$('#progressFill'),value=$('#progressValue'),syncState=$('#syncStatus'),stage=$('#syncStage');let timer=null,progress=0;
  if(run)run.addEventListener('click',()=>{progress=12;run.disabled=true;stop.disabled=false;syncState.className='status syncing';syncState.textContent='同步中';stage.textContent='正在比较文件';bar.style.width=progress+'%';value.textContent=progress+'%';timer=setInterval(()=>{progress=Math.min(92,progress+7);bar.style.width=progress+'%';value.textContent=progress+'%';if(progress>55)stage.textContent='正在传输文件'},600)});
  if(stop)stop.addEventListener('click',()=>{clearInterval(timer);syncState.textContent='正在停止';stage.textContent='等待当前文件安全停止';stop.disabled=true;setTimeout(()=>{syncState.className='status';syncState.textContent='已停止';stage.textContent='同步已停止';run.disabled=false;toast('同步已停止')},900)});
  const confirmInput=$('#confirmTextInput'),confirmSubmit=$('#confirmSubmitBtn');if(confirmInput&&confirmSubmit){confirmInput.addEventListener('input',()=>confirmSubmit.disabled=confirmInput.value!=='DELETE');confirmSubmit.addEventListener('click',e=>{e.preventDefault();confirmInput.closest('.modal').classList.remove('open');toast('操作已确认（原型未执行）')})}
  const historyFilter=$('#historyStatusFilter');if(historyFilter)historyFilter.addEventListener('change',()=>{$$('tbody tr[data-state]').forEach(row=>row.hidden=historyFilter.value&&row.dataset.state!==historyFilter.value)});
  const deviceSearch=$('#deviceSearch');if(deviceSearch)deviceSearch.addEventListener('input',()=>{const q=deviceSearch.value.trim().toLowerCase();$$('tbody tr[data-search]').forEach(row=>row.hidden=!row.dataset.search.toLowerCase().includes(q))});
  const requestBinding=(kind)=>window.dispatchEvent(new CustomEvent('syncraft:refresh-request',{detail:{kind}}));
  $$('[data-refresh-devices]').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;const state=$('#deviceLoadState');if(state)state.textContent='正在从管理状态接口刷新';try{const response=await fetch('/api/admin/state');if(!response.ok)throw new Error('state_request_failed');const data=await response.json();const list=$('#deviceList');const rows=Array.isArray(data.devices)?data.devices:[];if(!rows.length&&list)list.innerHTML='<tr><td colspan="8" class="empty-cell">暂无设备数据。</td></tr>';if(state)state.textContent=rows.length?'已获取设备数据，等待页面绑定':'暂无设备数据';requestBinding('devices');}catch(_){if(state)state.textContent='刷新失败，请检查 /api/admin/state'}finally{button.disabled=false}}));
  $$('[data-refresh-history]').forEach(button=>button.addEventListener('click',()=>{const state=$('#historyLoadState');if(state)state.textContent='已请求本机历史刷新，等待既有接口绑定';requestBinding('history')}));
  $$('[data-refresh-client]').forEach(button=>button.addEventListener('click',()=>{button.disabled=true;requestBinding('client-diagnostics');setTimeout(()=>{button.disabled=false},250);toast('已请求本机诊断刷新，等待既有接口绑定')}));
  const loadClaimState=async()=>{const space=$('#claimBucket'),device=$('#deviceName'),create=$('#createClaimBtn');if(!space||!device)return;space.disabled=true;device.disabled=true;create.disabled=true;space.innerHTML='<option value="">正在加载已创建的同步 ID…</option>';device.innerHTML='<option value="">正在加载已启用设备…</option>';try{const response=await fetch('/api/admin/state');if(!response.ok)throw new Error('state_request_failed');const state=await response.json();const spaces=Array.isArray(state.syncSpaces)?state.syncSpaces:[];const devices=Array.isArray(state.devices)?state.devices.filter(item=>item.enabled):[];space.innerHTML=spaces.length?spaces.map(item=>`<option value="${item.syncSpaceId}">${item.syncId}</option>`).join(''):'<option value="">暂无已创建的同步 ID；请先创建同步空间</option>';device.innerHTML=devices.length?devices.map(item=>`<option value="${item.id}">${item.name||item.id}</option>`).join(''):'<option value="">暂无已启用设备</option>';space.disabled=!spaces.length;device.disabled=!devices.length;create.disabled=!(spaces.length&&devices.length);$('#claimServiceStatus')?.replaceChildren(document.createTextNode(spaces.length&&devices.length?'真实状态已加载':'真实状态为空'));}catch(_){space.innerHTML='<option value="">无法加载同步 ID</option>';device.innerHTML='<option value="">无法加载已启用设备</option>';$('#claimServiceStatus')?.replaceChildren(document.createTextNode('真实接口加载失败'));toast('未能读取 /api/admin/state') }};
  const refreshClaim=$('#refreshClaimStateBtn');if(refreshClaim)refreshClaim.addEventListener('click',()=>{toast('正在刷新 /api/admin/state');loadClaimState()});if($('#claimBucket'))loadClaimState();
  const generate=$('#createClaimBtn');if(generate)generate.addEventListener('click',async()=>{const syncSpaceId=$('#claimBucket')?.value,deviceId=$('#deviceName')?.value,requestedRole=$('#claimRole')?.value;if(!syncSpaceId||!deviceId||!requestedRole)return;generate.disabled=true;try{const response=await fetch('/api/claims/create',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({syncSpaceId,deviceId,requestedRole})});if(!response.ok)throw new Error('claim_create_failed');const result=await response.json();$('#claimResultSyncId').textContent=result.syncId||'接口未返回 syncId';$('#claimResultDevice').textContent=result.deviceName||result.deviceId||deviceId;$('#claimResultRole').textContent=result.requestedRole||requestedRole;const masked=$('#claimMasked');masked.dataset.value=result.tKey||result.claimCode||'';masked.textContent='••••••••••••';$('#claimResult').classList.remove('hidden');toast('SyncKey 已按真实签发结果回显')}catch(_){toast('签发失败：请检查 /api/claims/create 返回')}finally{generate.disabled=false}});
  const login=$('#loginForm');if(login)login.addEventListener('submit',e=>{e.preventDefault();const input=$('#adminTokenInput');const msg=$('#authMessage');if(!input.value){msg.textContent='请输入管理 Token';msg.style.color='var(--danger)';return}location.href='server-overview.html'});
  window.addEventListener('keydown',e=>{if(e.key==='Escape')$$('.modal.open').forEach(closeModal)});
})();
